exec("import argparse,datetime as dt,re,sys\nfrom pathlib import Path\nR=['00_meta','10_knowledge','20_projects','50_memory']\nT={'knowledge':('10_knowledge','k'),'project':('20_projects','p'),'workflow':('30_workflows','w'),'skill':('40_skills','s'),'memory':('50_memory','m')}\nS=re.compile(r'(\\bsk-|ghp_|github_pat_|password\\s*:|api[_-]?key\\s*:)',re.I)\ndef fm(t):\n l=t.splitlines(); d={}\n if not l or l[0].strip()!='---': return d\n for x in l[1:]:\n  if x.strip()=='---': break\n  if ':' in x:\n   k,v=x.split(':',1); v=v.split('#',1)[0].strip().strip(chr(34)+chr(39)); d[k.strip()]=[z.strip().strip(chr(34)+chr(39)) for z in v[1:-1].split(',')] if v.startswith('[') and v.endswith(']') else v\n return d\ndef es(root):\n for p in sorted(Path(root).rglob('*.md')): yield p,fm(p.read_text(encoding='utf-8'))\ndef validate(root,level=1):\n root=Path(root); e=[]; ids={}; rec=[]\n for x in R:\n  if not (root/x).is_dir(): e.append('Pflichtordner fehlt: '+x)\n for p,m in es(root):\n  if not m: e.append('Frontmatter fehlt: '+str(p.relative_to(root))); continue\n  rec.append((p,m))\n  for k in ('id','type','title','created'):\n   if not m.get(k): e.append(str(p.relative_to(root))+': Pflichtfeld '+k+' fehlt')\n  i=str(m.get('id','')); typ=str(m.get('type',''))\n  if not (i.startswith(('doc-','moc-')) or re.fullmatch(r'[kpwsm]-\\d{4}-\\d{4}',i)): e.append(str(p.relative_to(root))+': ungueltige ID '+i)\n  if i in ids: e.append('Doppelte ID '+i)\n  ids[i]=p\n  if typ in T and not i.startswith(T[typ][1]+'-'): e.append(str(p.relative_to(root))+': ID-Prefix passt nicht zu type')\n  try: dt.date.fromisoformat(str(m.get('created')))\n  except (ValueError,TypeError): e.append(str(p.relative_to(root))+': created muss YYYY-MM-DD sein')\n  if typ=='project' and m.get('status') not in ('active','paused','completed','archived'): e.append(str(p.relative_to(root))+': ungueltiger Projektstatus')\n  if typ=='memory' and not m.get('scope'): e.append(str(p.relative_to(root))+': Memory braucht scope')\n  if S.search(p.read_text(encoding='utf-8')): e.append(str(p.relative_to(root))+': moegliches Secret')\n if level>=2:\n  for p,m in rec:\n   for i in m.get('links',[]) if isinstance(m.get('links',[]),list) else []:\n    if i not in ids: e.append(str(p.relative_to(root))+': Linkziel fehlt '+i)\n print('PAIOS Validation Level',level); [print('ERROR:',x) for x in e]; print(len(e),'Fehler'); return 1 if e else 0\ndef main():\n p=argparse.ArgumentParser(prog='paios'); s=p.add_subparsers(dest='c',required=True)\n v=s.add_parser('validate'); v.add_argument('vault'); v.add_argument('--level',type=int,default=1)\n i=s.add_parser('init'); i.add_argument('vault')\n n=s.add_parser('new'); n.add_argument('vault'); n.add_argument('kind',choices=sorted(T)); n.add_argument('title')\n q=s.add_parser('search'); q.add_argument('vault'); q.add_argument('term')\n a=p.parse_args()\n if a.c=='validate': sys.exit(validate(a.vault,a.level))\n if a.c=='init':\n  for x in R+['30_workflows','40_skills','90_archive']: Path(a.vault,x).mkdir(parents=True,exist_ok=True)\n  print('Vault initialisiert')\n if a.c=='search':\n  for p,_ in es(a.vault):\n   if a.term.lower() in p.read_text(encoding='utf-8').lower(): print(p)\n if a.c=='new':\n  folder,pre=T[a.kind]; root=Path(a.vault); used=[str(m.get('id')) for _,m in es(root)]; y=dt.date.today().year; nums=[int(x[-4:]) for x in used if x.startswith(pre+'-'+str(y)+'-') and x[-4:].isdigit()]; ident=pre+'-'+str(y)+'-'+format(max(nums,default=0)+1,'04d'); Path(root,folder).mkdir(parents=True,exist_ok=True); out=Path(root,folder,ident+'.md'); out.write_text('---\\nid: '+ident+'\\ntype: '+a.kind+'\\ntitle: '+chr(34)+a.title+chr(34)+'\\ncreated: '+dt.date.today().isoformat()+'\\n---\\n\\n# '+a.title+'\\n',encoding='utf-8'); print(out)\nif __name__=='__main__': main()")
